#include "dsp_block.h"

#if DSP4_BLOCK_KERNELS && DSP4_C2_MIX_FABRIC

#define C2MIX_MAX_SRC 23

.section/dm seg_dmda;

/* The gathered live source blocks and their compacted coefficients.
 * SCRATCH, shared by every chip-2 MIX_BUS node -- see the note above.
 * Sized for the widest bus in this graph (23 sources). */
.global _c2mix_src;
.var _c2mix_src[C2MIX_MAX_SRC*DSP4_BLOCK_SIZE];
.global _c2mix_gq;
.var _c2mix_gq[C2MIX_MAX_SRC];
/* r3 and r4 outlive the gather, which clobbers every R register it
 * can reach; they are parked here rather than juggled. */
.var _c2mix_out;
.var _c2mix_buf;

.section/pm seg_pmco;

.global _c2_mix_fabric;
_c2_mix_fabric:
    l0 = 0;
    l1 = 0;
    l2 = 0;
    l3 = 0;
    l4 = 0;
    dm(_c2mix_out) = r3;
    dm(_c2mix_buf) = r4;
    i0 = r0;                      /* the bus's coefficient row  */
    i1 = r2;                      /* its source block addresses */
    i2 = _c2mix_gq;
    i3 = _c2mix_src;
    r5 = 0;                       /* live crosspoints so far    */
    r9 = r1;                      /* declared crosspoints left  */

    /* ---- 1 + 2: compact the row, gather what survives ----
     * A SOFTWARE loop, not a hardware one: the body contains a
     * conditional branch AND a hardware loop of its own, and the
     * two-instruction tail a `do ... until lce` needs is not worth
     * the pair of instructions it would save on a per-BLOCK path. */
.cmf_scan:
    r6 = dm(i0, 1);               /* coefficient                */
    r7 = dm(i1, 1);               /* &_blk_<source>             */
    r6 = pass r6;
    if eq jump (pc, .cmf_dead);   /* a dead crosspoint is free  */
    dm(i2, 1) = r6;
    i4 = r7;
    lcntr = DSP4_BLOCK_SIZE, do .cmf_cp until lce;
        r8 = dm(i4, 1);
    .cmf_cp:
        dm(i3, 1) = r8;
    r5 = r5 + 1;
.cmf_dead:
    r9 = r9 - 1;
    if ne jump (pc, .cmf_scan);

    r13 = dm(_c2mix_out);
    i3 = r13;                     /* the block to publish       */
    r5 = pass r5;
    if eq jump (pc, .cmf_silent);

    /* ---- 3: bus-major accumulate ----
     * The MRF is cleared once a sample and stored once a sample; a
     * live crosspoint costs two loads and a MAC, which is chip 1's
     * `.fb_xp` exactly. Everything that can leave the sample loop
