     * `m1` walks one source in _c2mix_src and is put BACK TO 1 on
     * the way out -- chip 1's fabric leaves it moved and nothing
     * there reads it, but this pass runs in the middle of a chain
     * of node bodies written when m1 was 1. */
    m1 = DSP4_BLOCK_SIZE;
    r10 = _c2mix_src;             /* &src[0][sample]            */
    r11 = _c2mix_gq;
    r8 = 0x08000000;              /* 2^27, the rounding half    */
    r9 = 1;
    r12 = 0x7FFFFFFF;
    lcntr = DSP4_BLOCK_SIZE, do .cmf_smp until lce;
        i0 = r10;
        i1 = r11;
        mrf = 0;
        lcntr = r5, do .cmf_xp until lce;
            r0 = dm(i0, m1);      /* this source's sample       */
            r4 = dm(i1, 1);       /* its coefficient            */
