        r1 = mr0f;
        r2 = mr1f;
        r1 = lshift r1 by -28;
        r3 = lshift r2 by 4;
        r0 = r1 or r3;
        r7 = ashift r2 by -31;    /* 0 or -1: the sign hi implies */
        r6 = r12 xor r7;          /* ...the saturated value     */
        r1 = ashift r2 by -28;
        r3 = ashift r0 by -31;
        comp(r1, r3);
        if ne r0 = r6;
        dm(i3, 1) = r0;
    .cmf_smp:
        r10 = r10 + 1;            /* next sample, every source  */
    m1 = 1;
    r13 = dm(_c2mix_buf);
    i4 = r13;
    dm(i4, 0) = r0;               /* the staging word           */
    rts;

/* NOT A SPECIAL CASE, THE SAME ANSWER CHEAPLY. With every
